/* ===== SamStudy visual identity layer — colors/background only ===== */
body{
  background:
    radial-gradient(circle at 12% 8%,rgba(24,184,255,.16),transparent 24%),
    radial-gradient(circle at 88% 18%,rgba(139,92,246,.12),transparent 22%),
    radial-gradient(circle at 50% 100%,rgba(20,184,166,.10),transparent 28%),
    var(--bg);
}
body[data-page="home"]{--page-accent:#38bdf8;--page-accent2:#fbbf24;--page-glow:rgba(56,189,248,.20)}
body[data-page="batches"]{--page-accent:#a855f7;--page-accent2:#ec4899;--page-glow:rgba(168,85,247,.20)}
body[data-page="notes"]{--page-accent:#10b981;--page-accent2:#06b6d4;--page-glow:rgba(16,185,129,.18)}
body[data-page="quiz"]{--page-accent:#ec4899;--page-accent2:#f97316;--page-glow:rgba(236,72,153,.18)}
body[data-page="test"]{--page-accent:#ef4444;--page-accent2:#f59e0b;--page-glow:rgba(239,68,68,.18)}
body[data-page="three"]{--page-accent:#6366f1;--page-accent2:#22d3ee;--page-glow:rgba(99,102,241,.20)}
body[data-page="ai"]{--page-accent:#14b8a6;--page-accent2:#38bdf8;--page-glow:rgba(20,184,166,.18)}
body[data-page="profile"],body[data-page="profileType"]{--page-accent:#25b9ff;--page-accent2:#ffd447;--page-glow:rgba(37,185,255,.18)}

body[data-page] .page-heading .eyebrow{color:var(--page-accent2)}
body[data-page] .section-title .eyebrow{color:var(--page-accent2)}
body[data-page] .section-title h2,
body[data-page] .page-heading h1{
  background:linear-gradient(90deg,var(--page-accent2),var(--page-accent));
  -webkit-background-clip:text;background-clip:text;color:transparent;
}
body[data-page] .card,
body[data-page] .panel,
body[data-page] .selector,
body[data-page] .subject-card,
body[data-page] .question,
body[data-page] .analysis-q,
body[data-page] .permission{
  border-color:color-mix(in srgb,var(--page-accent) 45%,var(--border));
  box-shadow:0 18px 50px var(--page-glow);
}
body[data-page] .primary{
  background:linear-gradient(135deg,var(--page-accent2),var(--page-accent));
  box-shadow:0 10px 28px var(--page-glow);
}
body[data-page] .secondary{border-color:color-mix(in srgb,var(--page-accent) 48%,var(--border))}
body[data-page] .avatar{border-color:var(--page-accent)}
body[data-page] .option.selected .dot{background:var(--page-accent);border-color:var(--page-accent)}
body[data-page] .progress i{background:linear-gradient(90deg,var(--page-accent),var(--page-accent2),#ec4899)}
body[data-page] .bar{background:linear-gradient(180deg,var(--page-accent),var(--page-accent2))}
body[data-page] .appSectionGlow{background:radial-gradient(circle,var(--page-glow),transparent 70%)}

/* Profile colors from the approved SamStudy profile visual */
.profileColorCard{position:relative;overflow:hidden}
.profileColorCard::after{
  content:"";position:absolute;width:170px;height:170px;right:-65px;bottom:-70px;
  border-radius:50%;opacity:.14;filter:blur(2px);pointer-events:none;
  background:var(--profile-card-glow,#25b9ff);
}
.profileColorCard:nth-child(1){--profile-card-glow:#10b981}
.profileColorCard:nth-child(2){--profile-card-glow:#6366f1}
.profileColorCard:nth-child(3){--profile-card-glow:#ef4444}
.profileColorCard:nth-child(4){--profile-card-glow:#ec4899}

/* StudyShield option — same visual language, without changing navigation/layout */
.shieldConnect{
  display:flex;align-items:center;gap:12px;justify-content:space-between;
  padding:15px 17px;margin:0 0 14px;border:1px solid #22d3ee;border-radius:17px;
  background:linear-gradient(135deg,rgba(34,211,238,.12),rgba(239,68,68,.11));
  box-shadow:0 15px 40px rgba(34,211,238,.12);
}
.shieldConnect p{margin:4px 0 0;font-size:11px;color:var(--muted)}
.shieldIcon{
  width:48px;height:48px;min-width:48px;border-radius:15px;display:grid;place-items:center;
  background:linear-gradient(135deg,#ef4444,#06b6d4);color:#fff;font-size:23px;
  box-shadow:inset 0 0 18px rgba(255,255,255,.14);
}
body[data-page="profile"] .shieldConnect{
  border-color:#22d3ee;
  background:linear-gradient(135deg,rgba(34,211,238,.13),rgba(239,68,68,.12));
}
[data-theme="light"] .shieldConnect{
  background:linear-gradient(135deg,#ecfeff,#fff1f2);
}
@media(max-width:800px){
  .shieldConnect{align-items:flex-start;flex-direction:column}
  .shieldConnect .primary{width:100%}
}


/* ===== SamStudy 3D LIVE BACKGROUND — preserved + visibility fixed =====
   The same SamStudy logo remains visible as a perspective/depth layer.
   Content stays above it so cards, borders and text remain readable. */
.app{position:relative;isolation:isolate;overflow:clip}
.app:after{
  content:"";position:fixed;inset:78px 0 92px;z-index:0;pointer-events:none;
  background-image:var(--ss-logo);background-repeat:no-repeat;
  background-position:86% 43%;background-size:720px;
  opacity:.20;
  transform:perspective(1100px) rotateX(12deg) rotateY(-20deg) rotateZ(-5deg) scale(1.03);
  transform-origin:center;
  filter:drop-shadow(18px 24px 0 rgba(0,0,0,.20)) drop-shadow(0 0 44px rgba(37,185,255,.24));
  mix-blend-mode:normal;
  animation:ssLogoFloat 7s ease-in-out infinite;
  transition:background-position .35s ease,background-size .35s ease,transform .35s ease,opacity .35s ease;
}
.app > *{position:relative;z-index:1}
.header{z-index:100!important}.bottom{z-index:120!important}.modal{z-index:250!important}.toast{z-index:300!important}
@keyframes ssLogoFloat{
  0%,100%{margin-top:0;filter:drop-shadow(18px 24px 0 rgba(0,0,0,.20)) drop-shadow(0 0 44px rgba(37,185,255,.24))}
  50%{margin-top:-7px;filter:drop-shadow(20px 29px 0 rgba(0,0,0,.18)) drop-shadow(0 0 52px rgba(37,185,255,.30))}
}
[data-theme="light"] .app:after{
  opacity:.16;mix-blend-mode:multiply;
  filter:drop-shadow(12px 18px 0 rgba(18,40,60,.10)) drop-shadow(0 0 38px rgba(37,185,255,.20));
}
[data-theme="light"] body,[data-theme="light"] .app{color:#102235}
/* Light-mode contrast: borders, cards, controls and navigation remain visible. */
[data-theme="light"] .card,
[data-theme="light"] .panel,
[data-theme="light"] .selector,
[data-theme="light"] .subject-card,
[data-theme="light"] .question,
[data-theme="light"] .analysis-q,
