  box-shadow:0 16px 38px rgba(42,91,120,.12)!important;
}
[data-theme="light"] .home-feature p,
[data-theme="light"] .home-quote cite,
[data-theme="light"] .home-quote blockquote,
[data-theme="light"] .section-title p,
[data-theme="light"] .page p,
[data-theme="light"] .muted{color:#536b7c}
[data-theme="light"] .feature-btn,
[data-theme="light"] .quick-card,
[data-theme="light"] .secondary,
[data-theme="light"] .selector select,
[data-theme="light"] input,
