}
[data-theme="light"] .header,
[data-theme="light"] .bottom{border-color:rgba(20,145,195,.42)!important;background:rgba(245,250,253,.94)!important}
[data-theme="light"] .nav{color:#536b7c}
[data-theme="light"] .nav.active{color:#102235;background:#fff;box-shadow:0 10px 24px rgba(42,91,120,.14)}
@media(max-width:800px){
  .app:after{inset:74px 0 88px;background-position:78% 44%;background-size:500px;opacity:.19;transform:perspective(900px) rotateX(10deg) rotateY(-18deg) rotateZ(-4deg) scale(1.02)}
  [data-theme="light"] .app:after{opacity:.11}
  .home-feature{min-height:190px}
}
@media(prefers-reduced-motion:reduce){.app:after{animation:none}}

[data-theme=light] .hero h1{background:none;color:#102033}.hero h1 span{background:linear-gradient(90deg,#f2b900,#16b9ea);-webkit-background-clip:text;background-clip:text;color:transparent}
