/* Final SamStudy 3-D watermark: visible behind every page without reducing text contrast. */
.app{position:relative;isolation:isolate;}
.app:after{
  content:"";
  position:fixed;
  left:0; top:0; right:0; bottom:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--ss-bg-logo);
  background-repeat:no-repeat;
  background-position:50% 56%;
  background-size:min(82vw,720px) auto;
  opacity:.16;
  filter:saturate(1.18) contrast(1.08) drop-shadow(0 0 28px rgba(32,185,255,.24));
  transform:translate3d(0,0,0) rotate(-1deg) scale(1);
  transform-origin:center center;
  animation:ssSamStudyLogoFloat 9s ease-in-out infinite;
  will-change:transform,opacity;
}
@keyframes ssSamStudyLogoFloat{
  0%,100%{transform:translate3d(0,0,0) rotate(-1deg) scale(1);}
  50%{transform:translate3d(-8px,-10px,0) rotate(1deg) scale(1.025);}
}
/* Keep content surfaces readable over the 3-D watermark. */
.hero,.panel,.card,.quote,.social-card,.permission,.selector-card{position:relative;z-index:1;}
[data-theme="light"] .app:after{
  opacity:.09;
  filter:saturate(.92) contrast(1.18) brightness(.82) drop-shadow(0 0 24px rgba(25,130,190,.18));
}
@media (max-width:700px){
  .app:after{
    background-position:50% 58%;
    background-size:min(92vw,560px) auto;
    opacity:.15;
  }
  [data-theme="light"] .app:after{opacity:.08;}
}
@media (prefers-reduced-motion:reduce){.app:after{animation:none;}}



